INSERT INTO `answer` VALUES (1, 1, '------我们的应用程序旨在为电动汽车车主提供便捷、高效的充电服务。无论您身在何地，只需几个简单的步骤，您就可以方便地找到最近的充电站并开始...', 0, NULL, NULL);
